// Turns the client's 1-5 rating into: a Calificaciones row + the fixed reply + (1-3) an owner alert and an escalation.
// Convierte la nota 1-5 de la clienta en: fila de Calificaciones + respuesta fija + (1-3) alerta a la dueña y escalamiento.
// Input / entrada (from P31b - Lumière WhatsApp Inbound): { request: { lead_id, nombre, whatsapp, idioma, cita_id, servicio,
//   servicio_en, inicio, score, comment, texto, negocio } }
// 4-5 → Google review link (resena_pedida). 1-3 → no public review, owner alerted, case opened (alerta_duena).
// Google policy: everyone may review; we only choose WHEN to ask. Nothing is paid or gated.
const HIGH_MIN = 4;
const r = $input.first().json.request || $input.first().json;
const n = r.negocio || {};
const tz = n.zona_horaria || 'America/Phoenix';
const now = $now.setZone(tz);
const score = Math.round(Number(r.score));
if (!(score >= 1 && score <= 5) || !r.lead_id || !r.cita_id) {
  return [{ json: { ok: false, reason: 'invalid_request', score: r.score } }];
}
const lang = String(r.idioma || 'es').toLowerCase().startsWith('en') ? 'en' : 'es';
const nombre = String(r.nombre || '').trim().split(/\s+/)[0] || '';
const comment = String(r.comment || '').trim().slice(0, 500);
const high = score >= HIGH_MIN;
const link = n.link_resena_google || '';
const spa = n.nombre || 'Lumière Aesthetics';
const rand = () => Math.random().toString(36).slice(2, 7).toUpperCase();
const fecha = now.toFormat('yyyy-MM-dd HH:mm:ss');
const calId = 'CAL-' + now.toFormat('yyyyMMdd') + '-' + rand();

const T = {
  es: {
    high: `¡Gracias, ${nombre}! 💛 Nos alegra mucho que te haya ido tan bien. ¿Nos ayudas con una reseña en Google? Toma menos de un minuto y ayuda a otras mujeres a encontrarnos:\n${link}`,
    low: `Gracias por contarnos, ${nombre}, y lamentamos que tu experiencia no haya sido la que esperabas. Ya se lo comuniqué a la dirección de ${spa}. ¿Nos cuentas qué pasó? Una persona del equipo leerá tu mensaje y te escribirá por aquí muy pronto. 🤍`
  },
  en: {
    high: `Thank you, ${nombre}! 💛 We're so happy it went well. Would you help us with a Google review? It takes less than a minute and helps other women find us:\n${link}`,
    low: `Thank you for telling us, ${nombre}, and we're sorry your visit wasn't what you expected. I've already shared it with the management at ${spa}. Would you tell us what happened? Someone from the team will read your message and reach out here very soon. 🤍`
  }
};
const mensaje = T[lang][high ? 'high' : 'low'];
const resultado = high ? 'resena_pedida' : 'alerta_duena';
const out = {
  ok: true, score, high, resultado, mensaje, calificacion_id: calId,
  estado: high ? null : 'escalado',                         // null = P31b keeps its own estado
  cal_row: [calId, fecha, r.lead_id, r.cita_id, r.servicio, score, comment, resultado]
};

if (!high) {
  // Same escalation format as P31b (motivo queja): Sofía stays silent and forwards her messages until the team closes it.
  // Mismo formato de escalamiento que P31b (motivo queja): Sofía calla y le reenvía al equipo hasta que lo cierren.
  const escId = 'ESC-' + now.toFormat('yyyyMMdd') + '-' + rand();
  const resumen = `Low post-visit rating ${score}/5 for ${r.servicio_en || r.servicio} (${r.inicio}).` + (comment ? ` Comment: "${comment}"` : ' No comment yet.');
  out.escalamiento_id = escId;
  out.esc_row = [escId, r.lead_id, r.nombre, r.whatsapp, fecha, 'queja', resumen, 'abierto', '', ''];
  // Inputs of P31e - Lumière Send WhatsApp (rol alerta_equipo: logged under the client, hidden from her chat)
  out.alert = {
    lead_id: r.lead_id,
    whatsapp: '+' + String(n.whatsapp_equipo || '').replace(/\D/g, ''),
    rol: 'alerta_equipo', origen: 'P34',
    mensaje: [
      `⭐ LOW RATING ${score}/5 - act before it becomes a public review`,
      'Client: ' + r.nombre,
      'WhatsApp: ' + r.whatsapp,
      'Service: ' + (r.servicio_en || r.servicio) + ' (' + r.inicio + ')',
      comment ? 'Comment: "' + comment + '"' : 'Comment: (none yet, she was asked what happened)',
      'Case: ' + escId,
      'No review was requested. ' + (n.nombre_asistente || 'Sofía') + ' stops replying until you set estado = cerrado in Escalamientos.'
    ].join('\n')
  };
}
return [{ json: out }];

// Inputs of P31e - Lumière Send WhatsApp: the owner (Negocio.whatsapp_duena) and the team if it is another number.
// Entrada de P31e: la dueña (Negocio.whatsapp_duena) y el equipo si es otro número (nunca dos veces al mismo).
const a = $('Build Rating').first().json.alert;
const r = $('When Called').first().json;
const n = (r.request || r).negocio || {};
const norm = v => '+' + String(v || '').replace(/\D/g, '');
const to = [...new Set([norm(n.whatsapp_duena), norm(n.whatsapp_equipo)].filter(w => w.length >= 12))];
if (!to.length) return [{ json: a }];   // no number in Negocio: P31e logs the failure and the flow still returns / sin número: P31e registra el fallo y el flujo igual devuelve
return to.map((w, i) => ({ json: { ...a, whatsapp: w, rol: i === 0 && norm(n.whatsapp_duena) === w ? 'alerta_duena' : 'alerta_equipo' } }));

// What P31b gets back: the fixed reply for the client and her new Leads.estado (null = keep).
// Lo que recibe P31b: la respuesta fija para la clienta y su nuevo Leads.estado (null = se queda igual).
const b = $('Build Rating').first().json;
return [{ json: {
  ok: b.ok === true, reason: b.reason || '', score: b.score, resultado: b.resultado || '',
  mensaje: b.mensaje || '', estado: b.estado || null,
  calificacion_id: b.calificacion_id || '', escalamiento_id: b.escalamiento_id || ''
} }];
